package org.apache.commons.math3.distribution;

import org.junit.Test;
import static org.junit.Assert.assertEquals;

public class AgentBRT_Math_2_raw_diff_Test {

    @Test
    public void testReproduceBug() {
        // Parameters for the hypergeometric distribution
        int populationSize = 7;
        int numberOfSuccesses = 2;
        int sampleSize = 3;

        // Create the distribution
        HypergeometricDistribution distribution = new HypergeometricDistribution(populationSize, numberOfSuccesses, sampleSize);

        // Calculate the expected mean
        double expectedMean = sampleSize * ((double) numberOfSuccesses / populationSize);

        // Assert that the calculated mean matches the expected mean
        assertEquals("The calculated mean is incorrect.", expectedMean, distribution.getNumericalMean(), 1e-9);
    }
}

